import functools
def splits(w, C=4):
    c = w//C; d = w - C*c
    r = []
    for b in range(C):
        t = c+1 if b < d else c
        if t > 0: r.append(t)
    return r
@functools.lru_cache(None)
def R(w,h,C=4):
    if w==1 and h==1: return 1
    return 1 + sum(R(a,b,C) for a in splits(w,C) for b in splits(h,C))
for C in [2,3,4,5]:
    print(C, R(30,30,C))
