import sys, subprocess
sys.path.insert(0,'/tmp/maps')
from view import load
def run(w,h,n,s,params):
    out = subprocess.check_output(['./gen',str(w),str(h),str(n),str(s)]+[str(p) for p in params]).decode()
    open('/tmp/gen/tmp.txt','w').write(out)
    return load('/tmp/gen/tmp.txt')
def cmp(w,h,n,s,params):
    a = run(w,h,n,s,params); b = load('/tmp/maps/m_%d_%d_%d_%d.txt'%(w,h,n,s))
    if a[0]!=b[0] or a[1]!=b[1]: return ('dim', a[:2], b[:2])
    dp = sum(1 for x,y in zip(a[2],b[2]) if x!=y)
    do = sum(1 for x,y in zip(a[3],b[3]) if x!=y)
    ds = sum(1 for x,y in zip(a[4],b[4]) if x!=y)
    return dp, do, ds
if __name__=='__main__':
    params = sys.argv[1:]
    for s in [1,2,3,4,5]:
        print(s, cmp(30,30,1,s,params))
