// Procedural map generation: a recursive tree of randomly weighted regions,
// tessellated, reflected and shifted so that every player gets an equivalent
// start, then smoothed and scaled to integral strengths/productions.
#include "hlt.hpp"

#include <cmath>
#include <csignal>
#include <functional>
#include <iostream>
#include <memory>
#include <random>

namespace {

class Region {
public:
    double factor;
    std::vector<std::vector<std::unique_ptr<Region>>> children;

    Region(int w, int h, const std::function<double()> &rnd) {
        factor = std::pow(rnd(), 1.5);
        const int CHUNK = 4;
        if (w == 1 && h == 1) return;
        int cw = w / CHUNK, ch = h / CHUNK;
        int extraW = w - CHUNK * cw, extraH = h - CHUNK * ch;
        for (int a = 0; a < CHUNK; a++) {
            int th = a < extraH ? ch + 1 : ch;
            if (th <= 0) continue;
            children.emplace_back();
            for (int b = 0; b < CHUNK; b++) {
                int tw = b < extraW ? cw + 1 : cw;
                if (tw <= 0) continue;
                children.back().emplace_back(new Region(tw, th, rnd));
            }
        }
        // Smooth the factors of the children with their (toroidal) neighbours.
        const double OWN = 0.75;
        int H = (int)children.size(), W = (int)children[0].size();
        std::vector<std::vector<double>> blurred(H, std::vector<double>(W, 0));
        for (int a = 0; a < H; a++) {
            int up = a - 1, down = a + 1;
            if (up < 0) up += H;
            if (down == H) down = 0;
            for (int b = 0; b < W; b++) {
                int left = b - 1, right = b + 1;
                if (left < 0) left += W;
                if (right == W) right = 0;
                blurred[a][b] += children[a][b]->factor * OWN;
                blurred[a][b] += children[up][b]->factor * (1 - OWN) / 4;
                blurred[a][b] += children[down][b]->factor * (1 - OWN) / 4;
                blurred[a][b] += children[a][left]->factor * (1 - OWN) / 4;
                blurred[a][b] += children[a][right]->factor * (1 - OWN) / 4;
            }
        }
        for (int a = 0; a < H; a++)
            for (int b = 0; b < W; b++) children[a][b]->factor = blurred[a][b];
    }

    std::vector<std::vector<double>> getFactors() const {
        if (children.empty()) return std::vector<std::vector<double>>(1, std::vector<double>(1, factor));
        int H = (int)children.size(), W = (int)children[0].size();
        std::vector<std::vector<std::vector<std::vector<double>>>> sub(H, std::vector<std::vector<std::vector<double>>>(W));
        for (int a = 0; a < H; a++)
            for (int b = 0; b < W; b++) sub[a][b] = children[a][b]->getFactors();
        int width = 0, height = 0;
        for (int a = 0; a < H; a++) height += (int)sub[a][0].size();
        for (int b = 0; b < W; b++) width += (int)sub[0][b][0].size();
        std::vector<std::vector<double>> out(height, std::vector<double>(width));
        int y = 0;
        for (int my = 0; my < H; my++) {
            for (int iy = 0; iy < (int)sub[my][0].size(); iy++) {
                int x = 0;
                for (int mx = 0; mx < W; mx++) {
                    for (int ix = 0; ix < (int)sub[0][mx][0].size(); ix++) {
                        out[y][x] = sub[my][mx][iy][ix] * factor;
                        x++;
                    }
                }
                y++;
            }
        }
        return out;
    }
};

struct SiteD {
    unsigned char owner = 0;
    double strength = 0, production = 0;
};

} // namespace

namespace hlt {

Map::Map(short w, short h, unsigned char numberOfPlayers, unsigned int seed) {
    std::mt19937 prg(seed);
    std::uniform_real_distribution<double> urd(0.0, 1.0);
    std::function<double()> rnd = [&]() { return urd(prg); };

    // Decide whether more players go along the horizontal or the vertical.
    bool preferHorizontal = prg() % 2;

    int dw, dh;
    if (preferHorizontal) {
        dh = (int)std::sqrt((double)numberOfPlayers);
        while (numberOfPlayers % dh != 0) dh--;
        dw = numberOfPlayers / dh;
    } else {
        dw = (int)std::sqrt((double)numberOfPlayers);
        while (numberOfPlayers % dw != 0) dw--;
        dh = numberOfPlayers / dw;
    }

    int cw = w / dw;
    int ch = h / dh;
    // Make sure that the tessellation can be shifted by a uniform amount.
    if (preferHorizontal) {
        while (ch > 0 && ch % numberOfPlayers != 0) ch--;
    } else {
        while (cw > 0 && cw % numberOfPlayers != 0) cw--;
    }

    if (cw <= 0 || ch <= 0) {
        // The reference implementation dereferences empty containers here.
        std::raise(SIGSEGV);
        std::abort();
    }

    map_width = cw * dw;
    map_height = ch * dh;

    Region prodRegion(cw, ch, rnd);
    Region strRegion(cw, ch, rnd);
    std::vector<std::vector<double>> prodChunk = prodRegion.getFactors();
    std::vector<std::vector<double>> strChunk = strRegion.getFactors();

    const int MH = map_height, MW = map_width;

    // Tessellate the chunk and place the players at the chunk centres.
    std::vector<std::vector<SiteD>> tess(MH, std::vector<SiteD>(MW));
    for (int a = 0; a < dh; a++) {
        for (int b = 0; b < dw; b++) {
            for (int c = 0; c < ch; c++) {
                for (int d = 0; d < cw; d++) {
                    tess[a * ch + c][b * cw + d].production = prodChunk[c][d];
                    tess[a * ch + c][b * cw + d].strength = strChunk[c][d];
                }
            }
            tess[a * ch + ch / 2][b * cw + cw / 2].owner = (unsigned char)(a * dw + b + 1);
        }
    }

    // Reflect every other chunk.
    bool reflectV = dh % 2 == 0, reflectH = dw % 2 == 0;
    std::vector<std::vector<SiteD>> refl(MH, std::vector<SiteD>(MW));
    for (int a = 0; a < dh; a++) {
        for (int b = 0; b < dw; b++) {
            bool vr = reflectV && a % 2 != 0, hr = reflectH && b % 2 != 0;
            for (int c = 0; c < ch; c++)
                for (int d = 0; d < cw; d++)
                    refl[a * ch + c][b * cw + d] = tess[a * ch + (vr ? ch - c - 1 : c)][b * cw + (hr ? cw - d - 1 : d)];
        }
    }

    // Shift the chunks.
    std::vector<std::vector<SiteD>> shifted(MH, std::vector<SiteD>(MW));
    if (numberOfPlayers == 6) {
        shifted = refl;
    } else if (preferHorizontal) {
        int shift = (int)(prg() % dw) * (MH / dw);
        for (int a = 0; a < dh; a++)
            for (int b = 0; b < dw; b++)
                for (int c = 0; c < ch; c++)
                    for (int d = 0; d < cw; d++)
                        shifted[a * ch + c][b * cw + d] = refl[(a * ch + b * shift + c) % MH][b * cw + d];
    } else {
        int shift = (int)(prg() % dh) * (MW / dh);
        for (int a = 0; a < dh; a++)
            for (int b = 0; b < dw; b++)
                for (int c = 0; c < ch; c++)
                    for (int d = 0; d < cw; d++)
                        shifted[a * ch + c][b * cw + d] = refl[a * ch + c][(b * cw + a * shift + d) % MW];
    }

    // Final smoothing pass over the whole torus.
    const double OWN = 0.66667;
    std::vector<std::vector<SiteD>> blur = shifted;
    for (int z = 0; z <= 2 * std::sqrt((double)(MW * MH)) / 10; z++) {
        std::vector<std::vector<SiteD>> nb = blur;
        for (int a = 0; a < MH; a++) {
            int up = a - 1, down = a + 1;
            if (up < 0) up += MH;
            if (down == MH) down = 0;
            for (int b = 0; b < MW; b++) {
                int left = b - 1, right = b + 1;
                if (left < 0) left += MW;
                if (right == MW) right = 0;
                nb[a][b].strength *= OWN;
                nb[a][b].strength += blur[up][b].strength * (1 - OWN) / 4;
                nb[a][b].strength += blur[down][b].strength * (1 - OWN) / 4;
                nb[a][b].strength += blur[a][left].strength * (1 - OWN) / 4;
                nb[a][b].strength += blur[a][right].strength * (1 - OWN) / 4;
                nb[a][b].production *= OWN;
                nb[a][b].production += blur[up][b].production * (1 - OWN) / 4;
                nb[a][b].production += blur[down][b].production * (1 - OWN) / 4;
                nb[a][b].production += blur[a][left].production * (1 - OWN) / 4;
                nb[a][b].production += blur[a][right].production * (1 - OWN) / 4;
            }
        }
        blur = nb;
    }

    // Normalise.
    double maxP = 0, maxS = 0;
    for (auto &row : blur)
        for (auto &s : row) {
            if (s.production > maxP) maxP = s.production;
            if (s.strength > maxS) maxS = s.strength;
        }
    for (auto &row : blur)
        for (auto &s : row) {
            s.production /= maxP;
            s.strength /= maxS;
        }

    const int TOP_PROD = (int)(prg() % 10) + 6;
    const int TOP_STR = (int)(prg() % 106) + 150;

    contents.assign(MH, std::vector<Site>(MW));
    for (int a = 0; a < MH; a++) {
        for (int b = 0; b < MW; b++) {
            Site &s = contents[a][b];
            s.owner = blur[a][b].owner;
            s.strength = (unsigned char)std::round(blur[a][b].strength * TOP_STR);
            s.production = (unsigned char)std::round(blur[a][b].production * TOP_PROD);
            if (s.owner != 0 && s.production == 0) s.production = 1;
        }
    }

    std::cout << map_width << " " << map_height << std::endl;
}

} // namespace hlt
