        dw = numberOfPlayers / dh;
    } else {
        dw = (int)std::sqrt((double)numberOfPlayers);
        while (numberOfPlayers % dw != 0) dw--;
        dh = numberOfPlayers / dw;
    }

    int cw = w / dw;
    int ch = h / dh;
    // Make sure that the tessellation can be shifted by a uniform amount.
    if (preferHorizontal) {
        while (ch > 0 && ch % numberOfPlayers != 0) ch--;
    } else {
        while (cw > 0 && cw % numberOfPlayers != 0) cw--;
    }

    if (cw <= 0 || ch <= 0) {
        // The reference implementation dereferences empty containers here.
        std::raise(SIGSEGV);
        std::abort();
    }

    map_width = cw * dw;
    map_height = ch * dh;

    Region prodRegion(cw, ch, rnd);
    Region strRegion(cw, ch, rnd);
    std::vector<std::vector<double>> prodChunk = prodRegion.getFactors();
    std::vector<std::vector<double>> strChunk = strRegion.getFactors();

    const int MH = map_height, MW = map_width;

    // Tessellate the chunk and place the players at the chunk centres.
    std::vector<std::vector<SiteD>> tess(MH, std::vector<SiteD>(MW));
    for (int a = 0; a < dh; a++) {
        for (int b = 0; b < dw; b++) {
            for (int c = 0; c < ch; c++) {
                for (int d = 0; d < cw; d++) {
                    tess[a * ch + c][b * cw + d].production = prodChunk[c][d];
                    tess[a * ch + c][b * cw + d].strength = strChunk[c][d];
                }
            }
            tess[a * ch + ch / 2][b * cw + cw / 2].owner = (unsigned char)(a * dw + b + 1);
        }
    }

    // Reflect every other chunk.
    bool reflectV = dh % 2 == 0, reflectH = dw % 2 == 0;
    std::vector<std::vector<SiteD>> refl(MH, std::vector<SiteD>(MW));
    for (int a = 0; a < dh; a++) {
        for (int b = 0; b < dw; b++) {
            bool vr = reflectV && a % 2 != 0, hr = reflectH && b % 2 != 0;
            for (int c = 0; c < ch; c++)
                for (int d = 0; d < cw; d++)
                    refl[a * ch + c][b * cw + d] = tess[a * ch + (vr ? ch - c - 1 : c)][b * cw + (hr ? cw - d - 1 : d)];
        }
    }

    // Shift the chunks.
    std::vector<std::vector<SiteD>> shifted(MH, std::vector<SiteD>(MW));
    if (numberOfPlayers == 6) {
        shifted = refl;
    } else if (preferHorizontal) {
        int shift = (int)(prg() % dw) * (MH / dw);
        for (int a = 0; a < dh; a++)
            for (int b = 0; b < dw; b++)
                for (int c = 0; c < ch; c++)
                    for (int d = 0; d < cw; d++)
                        shifted[a * ch + c][b * cw + d] = refl[(a * ch + b * shift + c) % MH][b * cw + d];
    } else {
        int shift = (int)(prg() % dh) * (MW / dh);
        for (int a = 0; a < dh; a++)
            for (int b = 0; b < dw; b++)
                for (int c = 0; c < ch; c++)
                    for (int d = 0; d < cw; d++)
                        shifted[a * ch + c][b * cw + d] = refl[a * ch + c][(b * cw + a * shift + d) % MW];
    }

    // Final smoothing pass over the whole torus.
    const double OWN = 0.66667;
    std::vector<std::vector<SiteD>> blur = shifted;
    for (int z = 0; z <= 2 * std::sqrt((double)(MW * MH)) / 10; z++) {
        std::vector<std::vector<SiteD>> nb = blur;
        for (int a = 0; a < MH; a++) {
            int up = a - 1, down = a + 1;
            if (up < 0) up += MH;
            if (down == MH) down = 0;
            for (int b = 0; b < MW; b++) {
                int left = b - 1, right = b + 1;
                if (left < 0) left += MW;
                if (right == MW) right = 0;
                nb[a][b].strength *= OWN;
                nb[a][b].strength += blur[up][b].strength * (1 - OWN) / 4;
                nb[a][b].strength += blur[down][b].strength * (1 - OWN) / 4;
                nb[a][b].strength += blur[a][left].strength * (1 - OWN) / 4;
                nb[a][b].strength += blur[a][right].strength * (1 - OWN) / 4;
                nb[a][b].production *= OWN;
                nb[a][b].production += blur[up][b].production * (1 - OWN) / 4;
                nb[a][b].production += blur[down][b].production * (1 - OWN) / 4;
                nb[a][b].production += blur[a][left].production * (1 - OWN) / 4;
                nb[a][b].production += blur[a][right].production * (1 - OWN) / 4;
            }
        }
        blur = nb;
    }

    // Normalise.
    double maxP = 0, maxS = 0;
    for (auto &row : blur)
        for (auto &s : row) {
            if (s.production > maxP) maxP = s.production;
            if (s.strength > maxS) maxS = s.strength;
        }
    for (auto &row : blur)
        for (auto &s : row) {
            s.production /= maxP;
            s.strength /= maxS;
        }

    const int TOP_PROD = (int)(prg() % 10) + 6;
    const int TOP_STR = (int)(prg() % 106) + 150;

    contents.assign(MH, std::vector<Site>(MW));
    for (int a = 0; a < MH; a++) {
        for (int b = 0; b < MW; b++) {
            Site &s = contents[a][b];
            s.owner = blur[a][b].owner;
            s.strength = (unsigned char)std::round(blur[a][b].strength * TOP_STR);
            s.production = (unsigned char)std::round(blur[a][b].production * TOP_PROD);
            if (s.owner != 0 && s.production == 0) s.production = 1;
        }
    }

    std::cout << map_width << " " << map_height << std::endl;
}

