#include "networking.hpp"

#include <chrono>
#include <csignal>
#include <iostream>
#include <sstream>

#include <sys/prctl.h>
#include <sys/select.h>
#include <sys/wait.h>
#include <unistd.h>

std::string Networking::serializeMapSize(const hlt::Map &m) const {
    std::ostringstream oss;
    oss << m.map_width << ' ' << m.map_height << ' ';
    return oss.str();
}

std::string Networking::serializeProductions(const hlt::Map &m) const {
    std::ostringstream oss;
    for (auto &row : m.contents)
        for (auto &s : row) oss << (unsigned short)s.production << ' ';
    return oss.str();
}

std::string Networking::serializeMap(const hlt::Map &m) const {
    std::ostringstream oss;
    // Run-length encoded owners.
    unsigned short currentOwner = m.contents[0][0].owner;
    unsigned short counter = 0;
    for (auto &row : m.contents) {
        for (auto &s : row) {
            if (s.owner == currentOwner) {
                counter++;
            } else {
                oss << counter << ' ' << currentOwner << ' ';
                counter = 1;
                currentOwner = s.owner;
            }
        }
    }
    oss << counter << ' ' << currentOwner << ' ';
    // Strengths.
    for (auto &row : m.contents)
        for (auto &s : row) oss << (unsigned short)s.strength << ' ';
    return oss.str();
}

std::map<hlt::Location, unsigned char> Networking::deserializeMoveSet(const std::string &input, const hlt::Map &m) const {
    std::map<hlt::Location, unsigned char> moves;
    std::istringstream iss(input);
    hlt::Location l;
    int d;
    while (iss >> l.x >> l.y >> d && m.inBounds(l)) moves[l] = (unsigned char)d;
    return moves;
}

void Networking::sendString(unsigned char playerTag, std::string s) {
    s += '\n';
    const Connection &c = connections[playerTag - 1];
    size_t done = 0;
    while (done < s.size()) {
        ssize_t w = write(c.write, s.data() + done, s.size() - done);
        if (w <= 0) {
            if (!quiet_output) std::cout << "Problem writing to pipe\n";
            throw 1;
        }
        done += (size_t)w;
    }
}

std::string Networking::getString(unsigned char playerTag, unsigned int timeoutMillis) {
    std::string newString;
    auto tp = std::chrono::steady_clock::now();
    const Connection &c = connections[playerTag - 1];

    fd_set set;
    FD_ZERO(&set);
    FD_SET(c.read, &set);
    char buffer;

    while (true) {
        long long elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - tp).count();
        long long remaining = (long long)timeoutMillis - elapsed;
        if (remaining < 0) throw newString;
        struct timeval timeout;
        timeout.tv_sec = (time_t)(remaining / 1000);
        timeout.tv_usec = (suseconds_t)((remaining % 1000) * 1000);
        int selectionResult = select(c.read + 1, &set, NULL, NULL, &timeout);

        if (selectionResult > 0) {
            ssize_t r = read(c.read, &buffer, 1);
            if (r <= 0) continue;
            if (buffer == '\n') break;
            newString += buffer;
        } else {
            if (selectionResult < 0 && errno == EINTR) {
                FD_ZERO(&set);
                FD_SET(c.read, &set);
                continue;
            }
            std::string errorMessage = "Bot #" + std::to_string(playerTag) + " timeout or error (Unix) " +
                                       std::to_string(selectionResult) + '\n';
            if (!quiet_output) std::cout << errorMessage;
            throw newString;
        }
    }
    // Python turns \n into \r\n
    if (!newString.empty() && newString.back() == '\r') newString.pop_back();
    return newString;
}

void Networking::startAndConnectBot(const std::string &command) {
    if (!quiet_output) std::cout << command << "\n";

    int writePipe[2];
    int readPipe[2];
    if (pipe(writePipe)) {
        if (!quiet_output) std::cout << "Error creating pipe\n";
        throw 1;
    }
    if (pipe(readPipe)) {
        if (!quiet_output) std::cout << "Error creating pipe\n";
        throw 1;
    }

    pid_t ppidBeforeFork = getpid();
    pid_t pid = fork();
    if (pid == 0) {
        // Child.
        setpgid(getpid(), getpid());
        if (prctl(PR_SET_PDEATHSIG, SIGTERM) == -1) exit(1);
        if (getppid() != ppidBeforeFork) exit(1);

        dup2(writePipe[0], STDIN_FILENO);
        dup2(readPipe[1], STDOUT_FILENO);
        dup2(readPipe[1], STDERR_FILENO);
        close(writePipe[1]);
        close(readPipe[0]);

        execl("/bin/sh", "sh", "-c", command.c_str(), (char *)NULL);
        exit(1);
    } else if (pid < 0) {
        if (!quiet_output) std::cout << "Fork failed\n";
        throw 1;
    }

    Connection c;
    c.read = readPipe[0];
    c.write = writePipe[1];
    connections.push_back(c);
    processes.push_back(pid);
    player_logs.push_back(std::string());
}

int Networking::handleInitNetworking(unsigned char playerTag, const hlt::Map &m, bool ignoreTimeout, std::string *playerName) {
    const unsigned int ALLOTTED_MILLIS = ignoreTimeout ? 2147483647u : 30000u;
    std::string &log = player_logs[playerTag - 1];
    std::string response;
    try {
        std::string playerTagString = std::to_string(playerTag), mapSizeString = serializeMapSize(m),
                    mapString = serializeMap(m), prodString = serializeProductions(m);
        sendString(playerTag, playerTagString);
        sendString(playerTag, mapSizeString);
        sendString(playerTag, prodString);
        sendString(playerTag, mapString);
        std::string outMessage = "Init Message sent to player " + std::to_string(int(playerTag)) + ".\n";
        if (!quiet_output) std::cout << outMessage;

        log += " --- Init ---\n";

        auto initialTime = std::chrono::steady_clock::now();
        response = getString(playerTag, ALLOTTED_MILLIS);
        unsigned int millisTaken = (unsigned int)std::chrono::duration_cast<std::chrono::milliseconds>(
                                       std::chrono::steady_clock::now() - initialTime).count();

        log += response + "\n --- Bot used " + std::to_string(millisTaken) + " milliseconds ---";

        *playerName = response.substr(0, 30);
        if (!quiet_output) {
            std::string inMessage = "Init Message received from player " + std::to_string(int(playerTag)) + ", " + *playerName + ".\n";
            std::cout << inMessage;
        }

        log += "\n-----------------------------------------------------------------------------\n";
        return (int)millisTaken;
    } catch (std::string s) {
        if (s.empty()) log += "\nERRORED!\nNo response received.";
        else log += "\nERRORED!\nResponse received (if any):\n" + s;
        *playerName = "Bot #" + std::to_string(playerTag) + "; timed out during Init";
    } catch (...) {
        if (response.empty()) log += "\nERRORED!\nNo response received.";
        else log += "\nERRORED!\nResponse received (if any):\n" + response;
        *playerName = "Bot #" + std::to_string(playerTag) + "; timed out during Init";
    }
    return -1;
}

int Networking::handleFrameNetworking(unsigned char playerTag, unsigned short turnNumber, const hlt::Map &m, bool ignoreTimeout,
                                      std::map<hlt::Location, unsigned char> *moves) {
    const unsigned int ALLOTTED_MILLIS = ignoreTimeout ? 2147483647u : 1500u;
    std::string &log = player_logs[playerTag - 1];
    std::string response;
    try {
        if (isProcessDead(playerTag)) return -1;

        std::string mapString = serializeMap(m);
        sendString(playerTag, mapString);

        moves->clear();

        log += " --- Frame #" + std::to_string(turnNumber) + " ---\n";

        auto initialTime = std::chrono::steady_clock::now();
        response = getString(playerTag, ALLOTTED_MILLIS);
        unsigned int millisTaken = (unsigned int)std::chrono::duration_cast<std::chrono::milliseconds>(
                                       std::chrono::steady_clock::now() - initialTime).count();

        log += response + "\n --- Bot used " + std::to_string(millisTaken) + " milliseconds ---";

        for (char ch : response) {
            if (!(ch >= '0' && ch <= '9') && ch != ' ') {
                if (!quiet_output) std::cout << "Bot sent an invalid character - ejecting from game.\n";
                throw response;
            }
        }

        *moves = deserializeMoveSet(response, m);

        log += "\n-----------------------------------------------------------------------------\n";
        return (int)millisTaken;
    } catch (std::string s) {
        if (s.empty()) log += "\nERRORED!\nNo response received.";
        else log += "\nERRORED!\nResponse received (if any):\n" + s;
    } catch (...) {
        if (response.empty()) log += "\nERRORED!\nNo response received.";
        else log += "\nERRORED!\nResponse received (if any):\n" + response;
    }
    return -1;
}

bool Networking::isProcessDead(unsigned char playerTag) const { return processes[playerTag - 1] == -1; }

void Networking::killPlayer(unsigned char playerTag) {
    if (isProcessDead(playerTag)) return;

    std::string newString;
    const int PER_CHAR_WAIT = 10;  // millis
    const int MAX_READ_TIME = 1000; // millis

    const Connection &c = connections[playerTag - 1];
    fd_set set;
    FD_ZERO(&set);
    FD_SET(c.read, &set);
    char buffer;
    auto tp = std::chrono::steady_clock::now();
    while (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - tp).count() < MAX_READ_TIME) {
        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = PER_CHAR_WAIT * 1000;
        int selectionResult = select(c.read + 1, &set, NULL, NULL, &timeout);
        if (selectionResult > 0) {
            if (read(c.read, &buffer, 1) <= 0) break;
            newString += buffer;
        } else {
            break;
        }
    }

    if (!newString.empty())
        player_logs[playerTag - 1] += "\n --- Bot was killed. Below is the rest of its output (if any): ---\n" + newString + "\n --- End bot output ---";

    pid_t pid = processes[playerTag - 1];
    kill(-pid, SIGKILL);
    kill(pid, SIGKILL);
    waitpid(pid, NULL, WNOHANG);

    processes[playerTag - 1] = -1;
    connections[playerTag - 1].read = -1;
    connections[playerTag - 1].write = -1;
}
