#include "halite.hpp"

#include <algorithm>
#include <cmath>
#include <fstream>
#include <future>
#include <iostream>
#include <stdexcept>

#include "json.hpp"

Halite::Halite(unsigned short width, unsigned short height, unsigned int seed, unsigned short nPlayersForMap,
               Networking &networking_, bool ignoreTimeout)
    : networking(networking_) {
    number_of_players = networking.numberOfPlayers();
    ignore_timeout = ignoreTimeout;

    game_map = hlt::Map((short)width, (short)height, (unsigned char)nPlayersForMap, seed);

    // In single player mode, the extra players inserted by the generator are removed.
    if (number_of_players == 1) {
        for (auto &row : game_map.contents)
            for (auto &s : row)
                if (s.owner > 1) s.owner = 0;
    }

    player_names = std::vector<std::string>(number_of_players);
    full_frames.push_back(game_map);
    player_moves.resize(number_of_players);

    alive_frame_count = std::vector<int>(number_of_players, 1);
    last_territory_count = std::vector<unsigned int>(number_of_players, 1);
    full_territory_count = std::vector<unsigned int>(number_of_players, 1);
}

void Halite::removePlayerPieces(int playerIndex) {
    for (auto &row : game_map.contents)
        for (auto &s : row)
            if (s.owner == playerIndex + 1) s.owner = 0;
}

std::vector<bool> Halite::processNextFrame(std::vector<bool> alive) {
    // Communicate with all living bots concurrently.
    std::vector<std::future<int>> frameThreads(number_of_players);
    for (int a = 0; a < number_of_players; a++) {
        if (alive[a]) {
            frameThreads[a] = std::async(std::launch::async, &Networking::handleFrameNetworking, &networking,
                                         (unsigned char)(a + 1), turn_number, std::cref(game_map), ignore_timeout,
                                         &player_moves[a]);
        }
    }

    const unsigned short H = game_map.map_height, W = game_map.map_width;
    std::vector<std::vector<unsigned char>> moveDirections(H, std::vector<unsigned char>(W, 0));

    for (int a = 0; a < number_of_players; a++) {
        if (alive[a]) {
            int millis = frameThreads[a].get();
            if (millis < 0) {
                networking.killPlayer((unsigned char)(a + 1));
                timeout_tags.insert((unsigned short)(a + 1));
                removePlayerPieces(a);
                alive[a] = false;
                player_moves[a].clear();
            }
        }
    }

    std::vector<std::map<hlt::Location, unsigned char>> pieces(number_of_players);

    // Moves specified by the bots.
    for (int a = 0; a < number_of_players; a++) {
        if (!alive[a]) continue;
        for (auto &mv : player_moves[a]) {
            const hlt::Location &loc = mv.first;
            unsigned char dir = mv.second;
            if (!game_map.inBounds(loc)) continue;
            hlt::Site &site = game_map.getSite(loc);
            if (site.owner != a + 1) continue;

            if (dir == hlt::STILL) {
                if ((int)site.strength + site.production <= 255) site.strength += site.production;
                else site.strength = 255;
            }

            moveDirections[loc.y][loc.x] = dir;

            hlt::Location newLoc = game_map.getLocation(loc, dir);
            auto it = pieces[a].find(newLoc);
            if (it != pieces[a].end()) {
                if ((int)it->second + site.strength <= 255) it->second += site.strength;
                else it->second = 255;
            } else {
                pieces[a].insert(std::make_pair(newLoc, site.strength));
            }

            // A piece of strength zero stays behind on the vacated site.
            if (pieces[a].count(loc) == 0) pieces[a].insert(std::make_pair(loc, (unsigned char)0));

            site.owner = 0;
            site.strength = 0;
        }
    }

    // All remaining pieces stay still.
    for (unsigned short y = 0; y < H; y++) {
        for (unsigned short x = 0; x < W; x++) {
            hlt::Location l{x, y};
            hlt::Site &s = game_map.getSite(l);
            if (s.owner == 0) continue;
            if ((int)s.strength + s.production <= 255) s.strength += s.production;
            else s.strength = 255;
            auto &pm = pieces[s.owner - 1];
            auto it = pm.find(l);
            if (it != pm.end()) {
                if ((int)it->second + s.strength <= 255) it->second += s.strength;
                else it->second = 255;
            } else {
                pm.insert(std::make_pair(l, s.strength));
            }
            s.owner = 0;
            s.strength = 0;
        }
    }

    std::vector<std::map<hlt::Location, unsigned short>> toInjure(number_of_players);
    std::vector<std::vector<unsigned short>> injureMap(H, std::vector<unsigned short>(W, 0));

    for (unsigned short y = 0; y < H; y++) {
        for (unsigned short x = 0; x < W; x++) {
            hlt::Location l{x, y};
            for (int c = 0; c < number_of_players; c++) {
                if (!alive[c]) continue;
                auto pc = pieces[c].find(l);
                if (pc == pieces[c].end()) continue;
                unsigned short str = pc->second;
                for (int d = 0; d < number_of_players; d++) {
                    if (d == c || !alive[d]) continue;
                    hlt::Location targets[5] = {l, game_map.getLocation(l, hlt::NORTH), game_map.getLocation(l, hlt::EAST),
                                                game_map.getLocation(l, hlt::SOUTH), game_map.getLocation(l, hlt::WEST)};
                    for (auto &t : targets) {
                        if (pieces[d].count(t)) toInjure[d][t] += str;
                    }
                }
                hlt::Site &s = game_map.getSite(l);
                if (s.strength > 0) {
                    toInjure[c][l] += s.strength;
                    injureMap[y][x] += str;
                }
            }
        }
    }

    for (int a = 0; a < number_of_players; a++) {
        if (!alive[a]) continue;
        for (auto &inj : toInjure[a]) {
            auto it = pieces[a].find(inj.first);
            if (it == pieces[a].end()) continue;
            if (inj.second >= it->second) pieces[a].erase(it);
            else it->second -= (unsigned char)inj.second;
        }
    }

    for (unsigned short y = 0; y < H; y++) {
        for (unsigned short x = 0; x < W; x++) {
            hlt::Site &s = game_map.contents[y][x];
            if (s.strength < injureMap[y][x]) s.strength = 0;
            else s.strength -= (unsigned char)injureMap[y][x];
            s.owner = 0;
        }
    }

    for (int a = 0; a < number_of_players; a++) {
        for (auto &p : pieces[a]) {
            hlt::Site &s = game_map.getSite(p.first);
            s.owner = (unsigned char)(a + 1);
            s.strength = p.second;
        }
    }

    full_frames.push_back(game_map);
    full_player_moves.push_back(moveDirections);

    std::vector<bool> stillAlive(number_of_players, false);
    for (int a = 0; a < number_of_players; a++) last_territory_count[a] = 0;
    for (auto &row : game_map.contents) {
        for (auto &s : row) {
            if (s.owner != 0) {
                last_territory_count[s.owner - 1]++;
                stillAlive[s.owner - 1] = true;
            }
        }
    }
    for (int a = 0; a < number_of_players; a++) {
        full_territory_count[a] += last_territory_count[a];
        if (stillAlive[a]) alive_frame_count[a]++;
    }

    return stillAlive;
}

GameStatistics Halite::runGame(std::vector<std::string> *names, unsigned int seed, unsigned int id, bool enableReplay,
                               std::string replayDirectory) {
    std::vector<bool> result(number_of_players, true);
    std::vector<int> rankings;

    std::vector<std::future<int>> initThreads(number_of_players);
    for (int a = 0; a < number_of_players; a++) {
        initThreads[a] = std::async(std::launch::async, &Networking::handleInitNetworking, &networking, (unsigned char)(a + 1),
                                    std::cref(game_map), ignore_timeout, &player_names[a]);
    }
    for (int a = 0; a < number_of_players; a++) {
        int initMillis = initThreads[a].get();
        if (initMillis < 0) {
            result[a] = false;
            rankings.push_back(a);
            alive_frame_count[a] = 0;
            networking.killPlayer((unsigned char)(a + 1));
            timeout_tags.insert((unsigned short)(a + 1));
            removePlayerPieces(a);
        }
    }

    if (names != NULL) {
        player_names.clear();
        for (auto &n : *names) player_names.push_back(n.substr(0, 30));
    }

    const int maxTurnNumber = (int)(std::sqrt((double)(game_map.map_width * game_map.map_height)) * 10);

    while ((std::count(result.begin(), result.end(), true) > 1 || number_of_players == 1) && turn_number < maxTurnNumber) {
        turn_number++;
        if (!quiet_output) std::cout << "Turn " << turn_number << "\n";

        std::vector<bool> newResult = processNextFrame(result);

        std::vector<int> newRankings;
        for (int a = 0; a < number_of_players; a++)
            if (result[a] && !newResult[a]) newRankings.push_back(a);
        std::stable_sort(newRankings.begin(), newRankings.end(), [&](const int &u1, const int &u2) -> bool {
            if (last_territory_count[u1] == last_territory_count[u2]) return full_territory_count[u1] < full_territory_count[u2];
            return last_territory_count[u1] < last_territory_count[u2];
        });
        for (int r : newRankings) rankings.push_back(r);
        result = newResult;
    }

    std::vector<int> newRankings;
    for (int a = 0; a < number_of_players; a++)
        if (result[a]) newRankings.push_back(a);
    std::stable_sort(newRankings.begin(), newRankings.end(), [&](const int &u1, const int &u2) -> bool {
        if (last_territory_count[u1] == last_territory_count[u2]) return full_territory_count[u1] < full_territory_count[u2];
        return last_territory_count[u1] < last_territory_count[u2];
    });
    for (int r : newRankings) rankings.push_back(r);
    std::reverse(rankings.begin(), rankings.end());

    for (int a = 0; a < number_of_players; a++) networking.killPlayer((unsigned char)(a + 1));

    GameStatistics stats;
    std::string filename = std::to_string(id) + '-' + std::to_string(seed) + ".hlt";
    stats.output_filename = replayDirectory + filename;
    stats.replay_enabled = enableReplay;
    stats.map_seed = seed;

    if (enableReplay) {
        output(stats.output_filename);
        if (!quiet_output) {
            std::cout << "Map seed was " << seed << "\n";
            std::cout << "Opening a file at " << stats.output_filename << "\n";
        }
    }

    for (int a = 0; a < number_of_players; a++) {
        PlayerStatistics p;
        p.tag = a + 1;
        p.rank = (int)(std::distance(rankings.begin(), std::find(rankings.begin(), rankings.end(), a)) + 1);
        p.last_frame_alive = alive_frame_count[a] - 1;
        stats.player_statistics.push_back(p);
    }
    stats.timeout_tags = timeout_tags;

    for (unsigned short tag : timeout_tags) {
        std::string logName = std::to_string(tag) + '-' + std::to_string(id) + ".log";
        std::ofstream file(logName, std::ios_base::binary);
        file << networking.player_logs[tag - 1];
        file.flush();
        file.close();
        stats.timeout_log_filenames.push_back(logName);
    }

    return stats;
}

void Halite::output(const std::string &filename) {
    std::ofstream gameFile;
    gameFile.open(filename, std::ios_base::binary);
    if (!gameFile.is_open()) throw std::runtime_error("Could not open file for replay");

    const int H = game_map.map_height, W = game_map.map_width;
    std::string out;
    out.reserve(1 << 20);
    out += "{\"frames\":[";
    for (size_t f = 0; f < full_frames.size(); f++) {
        if (f) out += ',';
        out += '[';
        for (int y = 0; y < H; y++) {
            if (y) out += ',';
            out += '[';
            for (int x = 0; x < W; x++) {
                if (x) out += ',';
                const hlt::Site &s = full_frames[f].contents[y][x];
                out += '[';
                out += std::to_string((int)s.owner);
                out += ',';
                out += std::to_string((int)s.strength);
                out += ']';
            }
            out += ']';
        }
        out += ']';
    }
    out += "],\"height\":";
    out += std::to_string(H);
    out += ",\"moves\":[";
    for (size_t f = 0; f < full_player_moves.size(); f++) {
        if (f) out += ',';
        out += '[';
        for (int y = 0; y < H; y++) {
            if (y) out += ',';
            out += '[';
            for (int x = 0; x < W; x++) {
                if (x) out += ',';
                out += std::to_string((int)full_player_moves[f][y][x]);
            }
            out += ']';
        }
        out += ']';
    }
    out += "],\"num_frames\":";
    out += std::to_string(full_frames.size());
    out += ",\"num_players\":";
    out += std::to_string(player_names.size());
    out += ",\"player_names\":[";
    for (size_t i = 0; i < player_names.size(); i++) {
        if (i) out += ',';
        out += json::quote(player_names[i]);
    }
    out += "],\"productions\":[";
    for (int y = 0; y < H; y++) {
        if (y) out += ',';
        out += '[';
        for (int x = 0; x < W; x++) {
            if (x) out += ',';
            out += std::to_string((int)game_map.contents[y][x].production);
        }
        out += ']';
    }
    out += "],\"version\":11,\"width\":";
    out += std::to_string(W);
    out += '}';

    gameFile << out;
    gameFile.flush();
    gameFile.close();
}

std::ostream &operator<<(std::ostream &o, const GameStatistics &g) {
    if (g.replay_enabled) o << g.output_filename << ' ' << g.map_seed << std::endl;
    for (auto &p : g.player_statistics) o << p.tag << ' ' << p.rank << ' ' << p.last_frame_alive << std::endl;
    for (auto t : g.timeout_tags) o << t << ' ';
    if (g.timeout_tags.empty()) o << ' ';
    o << std::endl;
    for (auto &f : g.timeout_log_filenames) o << f << ' ';
    if (g.timeout_log_filenames.empty()) o << ' ';
    return o;
}
