// Minimal JSON string quoting compatible with the replay format.
#ifndef JSON_HPP
#define JSON_HPP

#include <string>

namespace json {

inline std::string quote(const std::string &s) {
    static const char hex[] = "0123456789abcdef";
    std::string out = "\"";
    for (unsigned char c : s) {
        switch (c) {
        case '"': out += "\\\""; break;
        case '\\': out += "\\\\"; break;
        case '\b': out += "\\b"; break;
        case '\f': out += "\\f"; break;
        case '\n': out += "\\n"; break;
        case '\r': out += "\\r"; break;
        case '\t': out += "\\t"; break;
        default:
            if (c <= 0x1f) {
                out += "\\u00";
                out += hex[c >> 4];
                out += hex[c & 0x0f];
            } else {
                out += (char)c;
            }
        }
    }
    out += '"';
    return out;
}

} // namespace json

#endif
