// A small command line parser reproducing the conventions of the classic
// "templatized C++ command line parser" style used by the game environment:
// short (-x) and long (--name) flags, combined switches (-qr), values in the
// same argument separated by a space ("-s 5"), "--" to stop flag processing and
// an unlabeled multi-value argument collecting everything else.
#ifndef CLI_HPP
#define CLI_HPP

#include <iosfwd>
#include <list>
#include <string>
#include <utility>
#include <vector>

namespace cli {

struct ArgException {
    std::string error;
    std::string id;
    std::string argId() const { return id == "undefined" ? std::string(" ") : "Argument: " + id; }
};

struct ExitException {
    int status;
};

class CmdLine;

class Arg {
public:
    Arg(const std::string &flag, const std::string &name, const std::string &desc, bool required, bool valueRequired)
        : flag_(flag), name_(name), desc_(desc), required_(required), valueRequired_(valueRequired) {}
    virtual ~Arg() {}

    virtual bool processArg(int *i, std::vector<std::string> &args) = 0;
    virtual std::string shortID() const;
    virtual std::string longID() const;
    virtual bool isUnlabeled() const { return false; }
    std::string toString() const;
    const std::string &getDescription() const { return desc_; }

protected:
    bool argMatches(const std::string &f) const;
    void trimFlag(std::string &f, std::string &value) const;
    bool hasBlanks(const std::string &s) const;

    std::string flag_, name_, desc_;
    bool required_, valueRequired_;
    bool alreadySet_ = false;
    bool ignoreable_ = true;
    std::string typeDesc_;

    friend class CmdLine;
};

class SwitchArg : public Arg {
public:
    enum Action { NONE, HELP, VERSION, IGNORE_REST };
    SwitchArg(const std::string &flag, const std::string &name, const std::string &desc, Action action = NONE)
        : Arg(flag, name, desc, false, false), action_(action) {}
    bool processArg(int *i, std::vector<std::string> &args) override;
    bool getValue() const { return value_; }
    void setCmdLine(CmdLine *c) { cmd_ = c; }

private:
    bool combinedSwitchesMatch(std::string &s);
    bool lastCombined(const std::string &s) const;
    void commonProcessing();
    bool value_ = false;
    Action action_;
    CmdLine *cmd_ = nullptr;
};

enum ValueKind { UNSIGNED_INT, INT_PAIR, STRING };

class ValueArg : public Arg {
public:
    ValueArg(const std::string &flag, const std::string &name, const std::string &desc, const std::string &typeDesc,
             ValueKind kind)
        : Arg(flag, name, desc, false, true), kind_(kind) {
        typeDesc_ = typeDesc;
    }
    bool processArg(int *i, std::vector<std::string> &args) override;
    std::string shortID() const override;
    std::string longID() const override;

    unsigned int uintValue = 0;
    std::pair<int, int> pairValue{0, 0};
    std::string stringValue;

private:
    void extractValue(const std::string &val);
    ValueKind kind_;
};

class UnlabeledMultiArg : public Arg {
public:
    UnlabeledMultiArg(const std::string &name, const std::string &desc, const std::string &typeDesc)
        : Arg("", name, desc, false, true) {
        typeDesc_ = typeDesc;
    }
    bool processArg(int *i, std::vector<std::string> &args) override;
    std::string shortID() const override;
    std::string longID() const override;
    bool isUnlabeled() const override { return true; }
    std::vector<std::string> values;
};

class CmdLine {
public:
    CmdLine(const std::string &message, const std::string &version);
    ~CmdLine();
    void add(Arg *a);
    void parse(int argc, char **argv);

    void usage(std::ostream &os);
    void version(std::ostream &os);
    void failure(const ArgException &e);

private:
    void shortUsage(std::ostream &os) const;
    void longUsage(std::ostream &os) const;
    static void spacePrint(std::ostream &os, const std::string &s, int maxWidth, int indentSpaces, int secondLineOffset);
    static bool emptyCombined(const std::string &s);

    std::list<Arg *> argList_;
    std::vector<Arg *> owned_;
    std::string message_, version_, progName_;
};

bool ignoringRest();

} // namespace cli

#endif
