#include "cli.hpp"

#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <sstream>

namespace cli {

static const char BLANK_CHAR = (char)7;
static const std::string FLAG_START = "-";
static const std::string NAME_START = "--";
static const char DELIMITER = ' ';
static bool g_ignoreRest = false;

bool ignoringRest() { return g_ignoreRest; }

std::string Arg::shortID() const {
    std::string id;
    if (!flag_.empty()) id = FLAG_START + flag_;
    else id = NAME_START + name_;
    if (valueRequired_) id += std::string(1, DELIMITER) + "<" + typeDesc_ + ">";
    if (!required_) id = "[" + id + "]";
    return id;
}

std::string Arg::longID() const {
    std::string id;
    if (!flag_.empty()) {
        id += FLAG_START + flag_;
        if (valueRequired_) id += std::string(1, DELIMITER) + "<" + typeDesc_ + ">";
        id += ",  ";
    }
    id += NAME_START + name_;
    if (valueRequired_) id += std::string(1, DELIMITER) + "<" + typeDesc_ + ">";
    return id;
}

std::string Arg::toString() const {
    std::string s;
    if (!flag_.empty()) s += FLAG_START + flag_ + " ";
    s += "(" + NAME_START + name_ + ")";
    return s;
}

bool Arg::argMatches(const std::string &f) const {
    return (f == FLAG_START + flag_ && !flag_.empty()) || f == NAME_START + name_;
}

void Arg::trimFlag(std::string &f, std::string &value) const {
    int stop = 0;
    for (size_t i = 0; i < f.length(); i++) {
        if (f[i] == DELIMITER) {
            stop = (int)i;
            break;
        }
    }
    if (stop > 1) {
        value = f.substr(stop + 1);
        f = f.substr(0, stop);
    }
}

bool Arg::hasBlanks(const std::string &s) const {
    for (size_t i = 1; i < s.length(); i++)
        if (s[i] == BLANK_CHAR) return true;
    return false;
}

// ---------------------------------------------------------------- switches

bool SwitchArg::lastCombined(const std::string &s) const {
    for (size_t i = 1; i < s.length(); i++)
        if (s[i] != BLANK_CHAR) return false;
    return true;
}

bool SwitchArg::combinedSwitchesMatch(std::string &s) {
    if (!s.empty() && s[0] != FLAG_START[0]) return false;
    if (s.substr(0, NAME_START.length()) == NAME_START) return false;
    if (s.find_first_of(DELIMITER) != std::string::npos) return false;
    for (size_t i = 1; i < s.length(); i++) {
        if (!flag_.empty() && s[i] == flag_[0] && flag_[0] != FLAG_START[0]) {
            s[i] = BLANK_CHAR;
            return true;
        }
    }
    return false;
}

void SwitchArg::commonProcessing() {
    if (alreadySet_) throw ArgException{"Argument already set!", toString()};
    alreadySet_ = true;
    value_ = !value_;
    switch (action_) {
    case HELP:
        cmd_->usage(std::cout);
        throw ExitException{0};
    case VERSION:
        cmd_->version(std::cout);
        throw ExitException{0};
    case IGNORE_REST:
        g_ignoreRest = true;
        break;
    default:
        break;
    }
}

bool SwitchArg::processArg(int *i, std::vector<std::string> &args) {
    if (ignoreable_ && g_ignoreRest) return false;
    if (argMatches(args[*i])) {
        commonProcessing();
        return true;
    } else if (combinedSwitchesMatch(args[*i])) {
        if (combinedSwitchesMatch(args[*i])) throw ArgException{"Argument already set!", toString()};
        commonProcessing();
        return lastCombined(args[*i]);
    }
    return false;
}

// ---------------------------------------------------------------- values

namespace {

// Mirrors the semantics of reading values with std::istream until exhausted.
template <typename T>
void extractStream(T &dest, const std::string &strVal) {
    std::istringstream is(strVal);
    int valuesRead = 0;
    while (is.good()) {
        if (is.peek() != EOF) is >> dest;
        else break;
        valuesRead++;
    }
    if (is.fail()) throw ArgException{"Couldn't read argument value from string '" + strVal + "'", "undefined"};
    if (valuesRead > 1) throw ArgException{"More than one valid value parsed from string '" + strVal + "'", "undefined"};
}

struct IntPair {
    std::pair<int, int> &p;
};

std::istream &operator>>(std::istream &is, IntPair ip) {
    is >> ip.p.first >> ip.p.second;
    return is;
}

} // namespace

void ValueArg::extractValue(const std::string &val) {
    try {
        if (kind_ == STRING) {
            stringValue = val;
        } else if (kind_ == UNSIGNED_INT) {
            extractStream(uintValue, val);
        } else {
            std::istringstream is(val);
            int valuesRead = 0;
            while (is.good()) {
                if (is.peek() != EOF) is >> IntPair{pairValue};
                else break;
                valuesRead++;
            }
            if (is.fail()) throw ArgException{"Couldn't read argument value from string '" + val + "'", "undefined"};
            if (valuesRead > 1) throw ArgException{"More than one valid value parsed from string '" + val + "'", "undefined"};
        }
    } catch (ArgException &e) {
        throw ArgException{e.error, toString()};
    }
}

bool ValueArg::processArg(int *i, std::vector<std::string> &args) {
    if (ignoreable_ && g_ignoreRest) return false;
    if (hasBlanks(args[*i])) return false;

    std::string f = args[*i];
    std::string value;
    trimFlag(f, value);

    if (argMatches(f)) {
        if (alreadySet_) throw ArgException{"Argument already set!", toString()};
        if (value.empty()) {
            (*i)++;
            if ((size_t)*i < args.size()) extractValue(args[*i]);
            else throw ArgException{"Missing a value for this argument!", toString()};
        } else {
            extractValue(value);
        }
        alreadySet_ = true;
        return true;
    }
    return false;
}

std::string ValueArg::shortID() const { return Arg::shortID(); }
std::string ValueArg::longID() const { return Arg::longID(); }

// ---------------------------------------------------------------- unlabeled

bool UnlabeledMultiArg::processArg(int *i, std::vector<std::string> &args) {
    if (hasBlanks(args[*i])) return false;
    values.push_back(args[*i]);
    alreadySet_ = true;
    return true;
}

std::string UnlabeledMultiArg::shortID() const { return "<" + typeDesc_ + "> ..."; }
std::string UnlabeledMultiArg::longID() const { return "<" + typeDesc_ + ">  (accepted multiple times)"; }

// ---------------------------------------------------------------- command line

CmdLine::CmdLine(const std::string &message, const std::string &version) : message_(message), version_(version) {
    SwitchArg *help = new SwitchArg("h", "help", "Displays usage information and exits.", SwitchArg::HELP);
    help->setCmdLine(this);
    add(help);
    owned_.push_back(help);
    SwitchArg *vers = new SwitchArg("", "version", "Displays version information and exits.", SwitchArg::VERSION);
    vers->setCmdLine(this);
    add(vers);
    owned_.push_back(vers);
    SwitchArg *ignore = new SwitchArg(FLAG_START, "ignore_rest", "Ignores the rest of the labeled arguments following this flag.",
                                      SwitchArg::IGNORE_REST);
    ignore->setCmdLine(this);
    add(ignore);
    owned_.push_back(ignore);
}

CmdLine::~CmdLine() {
    for (Arg *a : owned_) delete a;
}

void CmdLine::add(Arg *a) {
    if (a->isUnlabeled()) argList_.push_back(a);
    else argList_.push_front(a);
}

bool CmdLine::emptyCombined(const std::string &s) {
    if (!s.empty() && s[0] != FLAG_START[0]) return false;
    for (size_t i = 1; i < s.length(); i++)
        if (s[i] != BLANK_CHAR) return false;
    return true;
}

void CmdLine::parse(int argc, char **argv) {
    std::vector<std::string> args;
    for (int i = 0; i < argc; i++) args.push_back(argv[i]);

    bool shouldExit = false;
    int estat = 0;
    try {
        progName_ = args.empty() ? std::string() : args.front();
        if (!args.empty()) args.erase(args.begin());

        for (int i = 0; (size_t)i < args.size(); i++) {
            bool matched = false;
            for (Arg *a : argList_) {
                if (a->processArg(&i, args)) {
                    matched = true;
                    break;
                }
            }
            if (!matched && emptyCombined(args[i])) matched = true;
            if (!matched && !g_ignoreRest) throw ArgException{"Couldn't find match for argument", args[i]};
        }
    } catch (ArgException &e) {
        try {
            failure(e);
        } catch (ExitException &ee) {
            estat = ee.status;
            shouldExit = true;
        }
    } catch (ExitException &ee) {
        estat = ee.status;
        shouldExit = true;
    }
    if (shouldExit) exit(estat);
}

void CmdLine::version(std::ostream &os) {
    os << std::endl << progName_ << "  version: " << version_ << std::endl << std::endl;
}

void CmdLine::usage(std::ostream &os) {
    os << std::endl << "USAGE: " << std::endl << std::endl;
    shortUsage(os);
    os << std::endl << std::endl << "Where: " << std::endl << std::endl;
    longUsage(os);
    os << std::endl;
}

void CmdLine::failure(const ArgException &e) {
    std::cerr << "PARSE ERROR: " << e.argId() << std::endl << "             " << e.error << std::endl << std::endl;
    std::cerr << "Brief USAGE: " << std::endl;
    shortUsage(std::cerr);
    std::cerr << std::endl << "For complete USAGE and HELP type: " << std::endl
              << "   " << progName_ << " " << NAME_START << "help" << std::endl << std::endl;
    throw ExitException{1};
}

void CmdLine::shortUsage(std::ostream &os) const {
    std::string s = progName_ + " ";
    for (Arg *a : argList_) s += " " + a->shortID();
    int secondLineOffset = (int)progName_.length() + 2;
    if (secondLineOffset > 75 / 2) secondLineOffset = 75 / 2;
    spacePrint(os, s, 75, 3, secondLineOffset);
}

void CmdLine::longUsage(std::ostream &os) const {
    for (Arg *a : argList_) {
        spacePrint(os, a->longID(), 75, 3, 3);
        spacePrint(os, a->getDescription(), 75, 5, 0);
        os << std::endl;
    }
    os << std::endl;
    spacePrint(os, message_, 75, 3, 0);
}

void CmdLine::spacePrint(std::ostream &os, const std::string &s, int maxWidth, int indentSpaces, int secondLineOffset) {
    int len = (int)s.length();
    if ((len + indentSpaces > maxWidth) && maxWidth > 0) {
        int allowedLen = maxWidth - indentSpaces;
        int start = 0;
        while (start < len) {
            int stringLen = std::min<int>(len - start, allowedLen);
            if (stringLen == allowedLen)
                while (stringLen >= 0 && s[stringLen + start] != ' ' && s[stringLen + start] != ',' && s[stringLen + start] != '|')
                    stringLen--;
            if (stringLen <= 0) stringLen = allowedLen;
            for (int i = 0; i < stringLen; i++)
                if (s[start + i] == '\n') stringLen = i + 1;
            for (int i = 0; i < indentSpaces; i++) os << " ";
            if (start == 0) {
                indentSpaces += secondLineOffset;
                allowedLen -= secondLineOffset;
            }
            os << s.substr(start, stringLen) << std::endl;
            while (start + stringLen < len && s[stringLen + start] == ' ' && start < len) start++;
            start += stringLen;
        }
    } else {
        for (int i = 0; i < indentSpaces; i++) os << " ";
        os << s << std::endl;
    }
}

} // namespace cli
